-- Harare common brick and cement sellers, collected 2026-10-27 from public adverts and hardware store sites.
-- Re-runnable: matches existing sellers by name or phone, adds items and one advertised price per product.
do $$
declare r record; sid uuid; p jsonb;
begin
  for r in select * from jsonb_to_recordset('[{"n":"Benmark Bricks","ph":[],"t":null,"y":null,"pr":[["common_bricks","k1",95]],"u":"https://www.classifieds.co.zw/zimbabwe-cement-bricks"},{"n":"Galaxy Building Supplies","ph":[],"t":null,"y":null,"pr":[["common_bricks","k1",117.5],["cement","bag50",11]],"u":"https://www.classifieds.co.zw/zimbabwe-cement-bricks"},{"n":"T Rugara Pvt Ltd","ph":[],"t":null,"y":null,"pr":[["common_bricks","k1",130]],"u":"https://www.classifieds.co.zw/zimbabwe-cement-bricks"},{"n":"M&M Bricks","ph":[],"t":null,"y":null,"pr":[["common_bricks","k1",132.5],["cement","bag50",16]],"u":"https://www.classifieds.co.zw/zimbabwe-cement-bricks"},{"n":"M&H Suppliers","ph":[],"t":null,"y":null,"pr":[["common_bricks","k1",100],["cement","bag50",12]],"u":"https://www.classifieds.co.zw/zimbabwe-cement-bricks"},{"n":"Fine Bricks & Sands","ph":[],"t":null,"y":null,"pr":[["common_bricks","k1",95]],"u":"https://www.classifieds.co.zw/zimbabwe-cement-bricks"},{"n":"S Jacob Transport Services","ph":[],"t":null,"y":null,"pr":[["common_bricks","k1",170],["cement","bag50",12.75]],"u":"https://www.classifieds.co.zw/zimbabwe-cement-bricks"},{"n":"Openhomes Enterprises","ph":[],"t":null,"y":null,"pr":[["common_bricks","k1",103]],"u":"https://www.classifieds.co.zw/zimbabwe-cement-bricks"},{"n":"Excel Bricks & Quarry","ph":[],"t":null,"y":null,"pr":[["common_bricks","k1",100]],"u":"https://www.classifieds.co.zw/zimbabwe-cement-bricks"},{"n":"Rhinowall Hardware","ph":[],"t":null,"y":null,"pr":[["common_bricks","k1",125]],"u":"https://www.classifieds.co.zw/zimbabwe-cement-bricks"},{"n":"Rising Pier Investments","ph":[],"t":null,"y":null,"pr":[["common_bricks","k1",130]],"u":"https://www.classifieds.co.zw/zimbabwe-cement-bricks"},{"n":"Dawn Bricks And Quarry","ph":[],"t":null,"y":null,"pr":[["common_bricks","k1",109]],"u":"https://www.classifieds.co.zw/zimbabwe-cement-bricks"},{"n":"Chrisand Suppliers","ph":[],"t":null,"y":null,"pr":[["common_bricks","k1",120]],"u":"https://www.classifieds.co.zw/zimbabwe-cement-bricks"},{"n":"Kays Transport","ph":[],"t":null,"y":null,"pr":[["common_bricks","k1",120]],"u":"https://www.classifieds.co.zw/zimbabwe-cement-bricks"},{"n":"Real Link Suppliers","ph":[],"t":null,"y":null,"pr":[["common_bricks","k1",165]],"u":"https://www.classifieds.co.zw/zimbabwe-cement-bricks"},{"n":"Aaron Bricks Suppliers","ph":[],"t":null,"y":null,"pr":[["common_bricks","k1",72.5]],"u":"https://www.classifieds.co.zw/zimbabwe-cement-bricks"},{"n":"Borrowdale Stone Quarries","ph":[],"t":null,"y":null,"pr":[["common_bricks","k1",150],["cement","bag50",11]],"u":"https://www.classifieds.co.zw/zimbabwe-cement-bricks"},{"n":"C B Aggregate Quarry","ph":[],"t":null,"y":null,"pr":[["common_bricks","k1",105]],"u":"https://www.classifieds.co.zw/zimbabwe-cement-bricks"},{"n":"Couling Investments","ph":[],"t":null,"y":null,"pr":[["common_bricks","k1",120]],"u":"https://www.classifieds.co.zw/zimbabwe-cement-bricks"},{"n":"NickevBuild","ph":[],"t":null,"y":null,"pr":[["common_bricks","k1",125]],"u":"https://www.classifieds.co.zw/zimbabwe-cement-bricks"},{"n":"Elite Investments","ph":[],"t":null,"y":null,"pr":[["common_bricks","k1",null]],"u":"https://www.classifieds.co.zw/zimbabwe-cement-bricks"},{"n":"Gold Bricks & Hardware","ph":[],"t":null,"y":null,"pr":[["common_bricks","k1",110]],"u":"https://www.classifieds.co.zw/zimbabwe-cement-bricks"},{"n":"Hardercast Construction","ph":[],"t":null,"y":null,"pr":[["common_bricks","k1",110]],"u":"https://www.classifieds.co.zw/zimbabwe-cement-bricks"},{"n":"Kya Sands","ph":[],"t":null,"y":null,"pr":[["common_bricks","k1",90]],"u":"https://www.classifieds.co.zw/zimbabwe-cement-bricks"},{"n":"Supersands Construction","ph":[],"t":null,"y":null,"pr":[["common_bricks","k1",120]],"u":"https://www.classifieds.co.zw/zimbabwe-cement-bricks"},{"n":"Private brick seller (\u20265667)","ph":["+263772295667","+263773986214"],"t":null,"y":null,"pr":[["common_bricks","k1",105]],"u":"https://www.classifieds.co.zw/zimbabwe-cement-bricks"},{"n":"Private brick seller (\u20263964)","ph":["+263778553964"],"t":null,"y":null,"pr":[["common_bricks","k1",110]],"u":"https://www.classifieds.co.zw/zimbabwe-cement-bricks"},{"n":"Private cement seller (\u20261762)","ph":["+263773691762"],"t":null,"y":null,"pr":[["cement","bag50",13.5]],"u":"https://www.classifieds.co.zw/zimbabwe-cement-bricks"},{"n":"Private cement seller (\u20269502)","ph":["+263773339502"],"t":null,"y":null,"pr":[["cement","bag50",13]],"u":"https://www.classifieds.co.zw/zimbabwe-cement-bricks"},{"n":"Electrosales Hardware","ph":["+263771544227","+2638677222000"],"t":null,"y":null,"pr":[["cement","bag50",12.63]],"u":"https://www.electrosales.co.zw/shop/products/htbicm516"},{"n":"Highriders","ph":["+263772428181","+263772234615"],"t":"Hatfield","y":"70A Caledon Avenue, Prospect, Hatfield","pr":[["cement","bag50",10.5]],"u":"https://highriders.co.zw/product/ppc-cement-32-5/"},{"n":"Halsteds Builders Express (Msasa)","ph":[],"t":"Msasa","y":null,"pr":[["cement","bag50",12]],"u":"https://halsteds.co.zw/msasa_store/ppc-cement-surecem-32-5-50kg-harare.html"},{"n":"Union Hardware (Msasa)","ph":["+263786066409","+2638677911000"],"t":"Msasa","y":"196 Mutare Road, Msasa","pr":[["cement","bag50",null]],"u":"https://unionhardware.co.zw/msasa/product/cement-ppc-masonry-50kg/"}]'::jsonb) as x(n text, ph text[], t text, y text, pr jsonb, u text) loop
    select id into sid from public.sellers where name = r.n limit 1;
    if sid is null and cardinality(r.ph) > 0 then
      select seller_id into sid from public.seller_phones where phone = any(r.ph) limit 1;
    end if;
    if sid is null then
      insert into public.sellers (name, province, town, yard, categories, items, source, source_url)
      values (r.n, 'Harare', r.t, r.y, array['cement_bricks'], array[]::text[], 'lead', r.u) returning id into sid;
    end if;
    if cardinality(r.ph) > 0 then
      insert into public.seller_phones (phone, seller_id) select unnest(r.ph), sid on conflict do nothing;
    end if;
    for p in select * from jsonb_array_elements(r.pr) loop
      update public.sellers set
        items = (select array(select distinct unnest(items || array[p->>0]))),
        categories = (select array(select distinct unnest(categories || array['cement_bricks'])))
      where id = sid;
      if p->>2 is not null and not exists (select 1 from public.price_reports where seller_id = sid and item = p->>0 and source = 'listing') then
        insert into public.price_reports (seller_id, category_id, item, unit, price_usd, province, source, source_url, observed_on)
        values (sid, 'cement_bricks', p->>0, p->>1, (p->>2)::numeric, 'Harare', 'listing', r.u, date '2026-10-27');
      end if;
    end loop;
  end loop;
end $$;
